INSERT INTO "public"."funnel_configs" ("id", "data", "updated_at") VALUES (1, '{"seo":{"title":"Du học nghề Trung Quốc 2026 — Học bổng 75%,cam kết Visa","ogImage":"/og-image.jpg","keywords":"du học nghề trung quốc, học bổng trung quốc, du học vừa học vừa làm","faviconUrl":"data:image/jpeg;base64,","schemaType":"EducationalOrganization","description":"Chương trình du học nghề Trung Quốc trọn gói: học bổng miễn 100% KTX, vừa học vừa làm lương 15-25 triệu/tháng, cam kết Visa 100%. Đăng ký tư vấn miễn phí"},"fomo":{"names":["Trần Văn Nam","Nguyễn Thị Hà","Lê Minh Quân","Phạm Thu Trang","Hoàng Văn Dũng","Đỗ Thị Mai","Vũ Đức Anh","Bùi Thanh Tùng","Ngô Thị Lan","Đặng Hữu Phước"],"cities":["Bình Dương","Hà Nội","Bắc Giang","Nghệ An","Thanh Hóa","Hải Phòng","Đồng Nai","Thái Nguyên","Cần Thơ","Đắk Lắk"],"source":"recentLeads","enabled":true,"position":"left","template":"{name} ({city}) vừa đăng ký nhận tư vấn","displaySec":5,"maxDelaySec":18,"minDelaySec":10,"respectReducedMotion":true},"form":{"fields":[{"name":"name","type":"text","label":"Họ và tên","required":true,"placeholder":"Nguyễn Văn A"},{"name":"phone","type":"tel","label":"Số điện thoại","required":true,"placeholder":"09xx xxx xxx"},{"name":"email","type":"email","label":"Email (không bắt buộc)","required":false,"placeholder":"email@example.com"},{"name":"city","type":"select","label":"Tỉnh/Thành phố","required":true,"placeholder":"Chọn tỉnh/thành"},{"name":"major","type":"select","label":"Ngành học quan tâm","required":true,"placeholder":"Chọn ngành"}],"ctaLabel":"ĐĂNG KÝ NGAY","headline":"Đăng ký nhận tư vấn","webhookUrl":"https://hook.us2.make.com/jtwmjkp2t8wrlr4f080ppgc84u3e53aa","redirectUrl":"","rateLimitCount":3,"rateLimitWindowMin":5},"admin":{"password":"","adminPath":"admin","backupEmail":"noreply@duhoctrungquoc.com","storageMode":"database","supabaseUrl":"https://hzfxvpvbtnwhqcecyzzs.supabase.co","cronSchedule":"daily","backupCronToken":"","supabaseAnonKey":"","supabaseAdminEmail":""},"pages":[{"id":"home","kind":"landing","path":"","title":"Trang chủ","ctaHref":"#dang-ky","enabled":true,"heading":"","ctaLabel":"","menuOrder":0,"sectionIds":[],"showInMenu":false,"description":""},{"id":"thank-you","kind":"thankYou","path":"cam-on","title":"Cảm ơn","ctaHref":"/","enabled":true,"heading":"Cảm ơn bạn đã đăng ký!","ctaLabel":"Về trang chủ","menuOrder":1,"sectionIds":[],"showInMenu":false,"description":"Thông tin đã được ghi nhận. Tư vấn viên sẽ liên hệ với bạn trong thời gian sớm nhất."}],"theme":{"gold":"#f4cd4e","primary":"#2933c7","fontBody":"Be Vietnam Pro","fontHeading":"Be Vietnam Pro"},"abTest":{"split":50,"enabled":false,"variantACta":"","variantBCta":"","variantALabel":"Variant A","variantBLabel":"Variant B","variantAHeadline":"","variantBHeadline":""},"footer":{"logoUrl":"","menuLabel":"Liên kết nhanh","menuLinks":[{"href":"#dang-ky-cuoi","label":"Đăng ký tư vấn"},{"href":"#faq","label":"Câu hỏi thường gặp"}],"sponsorText":"Đơn vị bảo trợ chuyên môn & tuyển sinh: Công ty cổ phần hệ thống du học và việc làm quốc tế HLC. Chương trình được đề án 2 vành đai một con đường, chính phủ, tỉnh, trường, đại học, các doanh nghiệp và tập đoàn đa quốc gia áp dụng. Số giấy phép hoạt động :011047139"},"landing":{"faqs":[{"slug":"thoi_gian_hoc","answer":"Chương trình học 03 năm hệ Cao đẳng chính quy. Sau khi tốt nghiệp, sinh viên có thể liên thông lên Đại học nếu có nhu cầu.\\n\\nNăm đầu tiên chủ yếu học tiếng Trung, văn hóa, lịch sử và các kiến thức hội nhập; đồng thời làm quen với môi trường học tập, sinh hoạt tại Trung Quốc.","question":"Chương trình học bao nhiêu năm?"},{"slug":"luong_thuc_hanh","answer":"Có. Mỗi năm, sinh viên có khoảng 08 tháng thực hành hưởng lương và chỉ học lý thuyết tại trường khoảng 04 tháng.\\n\\nMức thu nhập thực hành thường đủ để trang trải chi phí sinh hoạt trong suốt quá trình học. Nếu chi tiêu hợp lý, nhiều bạn còn có thể tích lũy một khoản vốn trước khi tốt nghiệp.","question":"Lương thực hành có đủ để trang trải chi phí không?"},{"slug":"bang_tot_nghiep","answer":"Sinh viên được cấp bằng Cao đẳng chính quy do trường tại Trung Quốc cấp, có thể liên thông lên Đại học và được công nhận tại hơn 30 quốc gia theo quy định, thỏa thuận công nhận văn bằng của từng nước.","question":"Sau khi tốt nghiệp sẽ nhận bằng gì?"},{"slug":"ky_nhap_hoc","answer":"Thông thường chương trình có 02 kỳ nhập học:\\n\\n• Kỳ tháng 3\\n• Kỳ tháng 9","question":"Mỗi năm có bao nhiêu kỳ nhập học?"},{"slug":"dieu_kien_tuyen_sinh","answer":"Học viện Kỹ sư Quế Lâm\\n• Độ tuổi: Dưới 35 tuổi\\n• Trình độ: Tốt nghiệp THCS trở lên\\n\\nĐại học Khoa học Kỹ thuật Điện tử Quế Lâm (GUET)\\n• Độ tuổi: Dưới 30 tuổi\\n• Trình độ: Tốt nghiệp THPT trở lên\\n\\nĐại học Nghề nghiệp Nam Thông (tỉnh Giang Tô)\\n• Độ tuổi: Dưới 25 tuổi\\n• Trình độ: Tốt nghiệp THPT trở lên","question":"Chương trình nhận độ tuổi và trình độ như thế nào?"}],"pains":["Làm công nhân 10-12 tiếng/ngày, lương không tăng, tay nghề không lên.Đầu tháng nhận lương cuối tháng hết luôn.","Không có bằng cấp quốc tế nên mãi không thoát khỏi vị trí lao động phổ thông,và tiền đồ sự nghiệp mù mịt.","Muốn đi nước ngoài nhưng sợ chi phí hàng trăm triệu và rủi ro môi giới.Xung quanh nhà toàn là tập đoàn trung quốc mà bản thân không biết tiếng Trung"],"stats":[{"label":"Học  bổng 75%  trong 3 năm","value":"75%"},{"label":"Thực hành có lương từ 12-30triệu/tháng","value":"3-8000NDT"},{"label":"Ngành công nghệ đang khát nhân lực","value":"8-20"},{"label":"Giới thiệu việc làm sau tốt nghiệp","value":"Được"}],"steps":[{"title":"Đăng ký & tư vấn 1:1","number":"01","description":"Điền form, chuyên viên gọi lại trong 30 phút, gửi lộ trình chi tiết."},{"title":"Chọn ngành & xét hồ sơ","number":"02","description":"Chọn 1 trong 8-20 ngành hot, hoàn thiện hồ sơ theo hướng dẫn từng bước."},{"title":"Học tiếng Trung &  hoàn thiện hồ sơ","number":"03","description":"Đào tạo tiếng Trung cở bản và kỹ năng trước khi bay."},{"title":" Phỏng vấn -Xin Visa xuất cảnh - Nhập học","number":"04","description":"Sang trường đối tác, học nghề và làm việc có lương ngay từ kỳ đầu."}],"experts":[{"bio":"Tập trung đánh giá năng lực, sở thích và mục tiêu dài hạn để giúp học viên chọn ngành phù hợp.","name":" Nguyễn Thị Nguyệt","role":"TRỢ LÝ TGĐ","experience":"Kinh nghiệm tư vấn lộ trình học nghề quốc tế và định hướng nghề nghiệp sau tốt nghiệp."},{"bio":"Đồng hành cùng học viên từ bước rà soát điều kiện đến hoàn thiện hồ sơ nhập học và visa.","name":"Nguyễn Thị Hương ","role":"TRƯỞNG PHÒNG TUYỂN SINH","experience":"Kinh nghiệm xử lý hồ sơ tuyển sinh, thủ tục du học và chuẩn bị trước khi xuất cảnh."},{"bio":"Hỗ trợ học viên chuẩn bị ngôn ngữ, kỹ năng thích nghi và kế hoạch học tập tại Trung Quốc.","name":"Ông Đỗ Thanh Đại","role":"GIÁM ĐỐC DỰ ÁN DHN TQ","experience":"Kinh nghiệm đào tạo kỹ năng tiền du học và hỗ trợ học viên trong quá trình hòa nhập."}],"logoUrl":"data:image/webp;base64,","benefits":[{"stat":"75%","text":" Đề án 1 vành đai 1 con đường của chính phủ tỉnh với các trường đại học cùng các doanh nghiệp & tập đoạn đa quốc gia triển khai","title":"Học bổng 75%"},{"stat":"80%","text":"Chỉ 20% lý thuyết. Bạn làm việc trực tiếp trên dây chuyền, máy móc và công nghệ mới nhất.","title":"80% thực hành"},{"stat":"12-30tr","text":"Vừa học vừa làm, thu nhập 12-30 triệu/tháng, đủ chi phí sinh hoạt và gửi về gia đình.","title":"Lương cứng mỗi tháng"},{"stat":"Bằng","text":"Bằng Cao đẳng chính quy được liên thông và công nhận quốc tế, mở đường ở lại làm việc hoặc học tiếp.","title":"Cao đẳng chính quy quốc tế"}],"showLogo":true,"brandName":"Hệ thống du học và việc làm quốc tế HLC","heroTitle":"Tương lai không tự thay đổi nếu hôm nay bạn không dám","watermark":{"text":"HLC GROUP","enabled":false,"opacity":0.35},"faqHeading":"Câu hỏi thường gặp","majorIcons":["🚗","🛸","🛒","🚚","🔌","📡","⚙️","🀄"],"majorNames":["Công nghệ Ô tô điện","Công nghệ Drone (UAV)","Thương mại điện tử","Logistics & Chuỗi cung ứng","Kỹ thuật Điện tử","IoT - Internet vạn vật","Cơ khí tự động hóa","Hán ngữ thương mại"],"heroEyebrow":"Tuyển sinh kỳ tháng 3 & tháng 9","painHeading":"Nếu bạn đang gặp một trong ba điều này, bạn cần đọc tiếp","heroCtaLabel":"Nhận lộ trình phù hợp","heroImageUrl":"data:image/webp;base64,","stepsHeading":"Lộ trình 4 bước đơn giản","testimonials":[{"meta":"Ngành Ô tô điện · Quảng Châu · khóa tháng 9","name":"Nguyễn Văn Hùng","text":"Trước em làm xưởng gỗ 7 triệu/tháng. Sang đây vừa học vừa làm được hơn 20 triệu, tháng nào cũng gửi về nhà 10 triệu. Tay nghề lên hẳn vì được làm trên xe thật.","avatarUrl":"data:image/png;base64,"},{"meta":"Ngành Thương mại điện tử · Nghĩa Ô","name":"Trần Ngọc Vân","text":"Em không biết tiếng Trung, được học nền tảng trước khi bay nên sang không bị choáng. Giờ em phụ trách livestream cho một shop, thu nhập ổn định.","avatarUrl":"data:image/png;base64,"},{"meta":"Ngành Drone (UAV) · Thâm Quyến","name":"Trần Thị Ngọc","text":"Nhà em không đủ tiền cho đi du học tự túc. Chương trình giúp em học ngành công nghệ mà chi phí ban đầu rất nhẹ. Ra trường có bằng Cao đẳng chính quy.","avatarUrl":"data:image/png;base64,"}],"heroHighlight":"lựa chọn.","heroMediaMode":"image","majorsHeading":"8-20 ngành nghề phát triển trong 5 năm tới","sectionsArray":[{"id":"hero","type":"hero","label":"Hero","order":0,"enabled":true},{"id":"stats","type":"stats","label":"Stats","order":1,"enabled":true},{"id":"pains","type":"pains","label":"Pain points","order":2,"enabled":true},{"id":"benefits","type":"benefits","label":"Benefits","order":3,"enabled":true},{"id":"majors","type":"majors","label":"Ngành học","order":4,"enabled":true},{"id":"experts","type":"experts","label":"Chuyên gia","order":5,"enabled":true},{"id":"gallery","type":"gallery","label":"Gallery","order":6,"enabled":true},{"id":"testimonials","type":"testimonials","label":"Testimonials","order":7,"enabled":true},{"id":"steps","type":"steps","label":"Lộ trình","order":8,"enabled":true},{"id":"faq","type":"faq","label":"FAQ","order":9,"enabled":true},{"id":"finalCta","type":"finalCta","label":"CTA cuối","order":10,"enabled":true},{"id":"september-2026-offer","type":"offer","label":"Ưu đãi tháng 9/2026","order":1,"content":{"body":"Đăng ký tham gia chương trình trước ngày 28/09/2026 để nhận ngay:\\n\\n🎁 ƯU ĐÃI TRỊ GIÁ 2.000.000 ĐỒNG\\n\\n⏰ Số lượng ưu đãi có hạn. Áp dụng cho hồ sơ đăng ký và hoàn tất thủ tục theo quy định trước ngày 28/09/2026.\\n\\n👉 Đừng bỏ lỡ cơ hội trở thành du học sinh nghề Trung Quốc với nhiều chính sách hỗ trợ hấp dẫn!","heading":"🎉 Ưu đãi đặc biệt - Tháng 9/2026 🎉","variant":"offer","imageUrl":"","textColor":"","buttonHref":"#dang-ky","accentColor":"","buttonLabel":"Đăng ký nhận ưu đãi 2.000.000đ","backgroundColor":""},"enabled":true}],"copyProtection":{"enabled":true,"blockImageDrag":true,"blockContextMenu":true,"disableSelection":true},"expertsHeading":"Đội ngũ chuyên gia tư vấn","galleryHeading":"Hình ảnh thực tế: visa, trường học & ký túc xá","gallerySliders":[{"id":"ky-ket","enabled":true,"heading":"Hình ảnh ký kết hợp tác","captions":[],"imageUrls":[],"description":"Các buổi lễ ký kết hợp tác giữa trung tâm và trường đại học, doanh nghiệp đối tác tại Trung Quốc.","insertAfter":"gallery"},{"id":"dantoc-quangtay","enabled":true,"heading":"Trường Đại học Dân tộc Quảng Tây","captions":[],"imageUrls":[],"description":"Khuôn viên, cơ sở vật chất và môi trường học tập tại Trường Đại học Dân tộc Quảng Tây.","insertAfter":"gallery"},{"id":"congnghe-qualam","enabled":true,"heading":"Trường Đại học Công nghệ Kỹ thuật Quế Lâm — Học viện Công nghệ Quảng Tây","captions":[],"imageUrls":[],"description":"Học viên được các tập đoàn lớn tiếp nhận vào làm việc thực tập ngay trong quá trình học, tiếp cận công nghệ và dây chuyền sản xuất tiên tiến.","insertAfter":"gallery"},{"id":"dh-qualam","enabled":true,"heading":"Trường Đại học Quế Lâm","captions":[],"imageUrls":[],"description":"Cơ sở đào tạo và khuôn viên Trường Đại học Quế Lâm — đối tác tuyển sinh của chương trình.","insertAfter":"gallery"}],"heroTrustItems":["Học bổng lên đến 75%","Không cần chứng chỉ HSK trước khi nhập học","Không chứng minh tài chính","Tốt nghiệp nhận bằng Cao đẳng chính quy, có thể liên thông Đại học","Drone/Flycam - thực hành với hệ sinh thái DJI","Công nghệ ô tô điện - định hướng thực hành theo hệ sinh thái BYD","Thương mại điện tử, AI, IoT và Smart Home"],"benefitsHeading":"4 lợi ích vàng của chương trình","expertImageUrls":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"finalCtaHeading":"Đổi 30 giây hôm nay cho 5 năm tới của bạn","galleryCaptions":[],"graduationBadge":"Khóa 2023-2026 Tốt nghiệp","heroDescription":"Bạn đang làm công nhân trong nhà máy, xí nghiệp?\\nBạn đang làm công việc thu nhập thấp và chưa thấy tương lai?\\nHay bạn vẫn chưa biết nên học gì để có một nghề ổn định?\\n\\nDu học nghề Trung Quốc - vừa học, vừa thực hành có lương từ 15-30 triệu/tháng.","galleryImageUrls":[],"heroSliderImages":[],"graduationHeading":"Lễ tốt nghiệp chính quy tại Trường Đại học Công nghệ Điện tử Quế Lâm","imageOptimization":{"quality":0.82,"convertUploadsToWebp":true},"majorDescriptions":["Đón đầu xu hướng điện hóa giao thông, pin thế hệ mới và hệ sinh thái xe thông minh.","Phát triển cùng nhu cầu UAV trong nông nghiệp, vận chuyển, khảo sát và cứu hộ.","Mở rộng theo thương mại xuyên biên giới, bán hàng đa kênh và vận hành bằng dữ liệu.","Giữ vai trò cốt lõi khi chuỗi cung ứng khu vực ngày càng tự động hóa và kết nối sâu.","Là nền tảng cho thiết bị thông minh, năng lượng sạch, robot và sản xuất công nghệ cao.","Kết nối nhà máy, đô thị và thiết bị thông minh trong nền kinh tế số tương lai.","Thúc đẩy nhà máy thông minh, robot cộng tác và dây chuyền sản xuất ít phụ thuộc lao động tay chân.","Tạo lợi thế trong thương mại, dịch vụ và hợp tác doanh nghiệp Việt Nam – Trung Quốc."],"majorsDescription":"Các lựa chọn bám sát chuyển dịch công nghệ, sản xuất và thương mại giữa Việt Nam – Trung Quốc.","expertsDescription":"Đồng hành từ lúc chọn ngành, chuẩn bị hồ sơ đến khi học viên sẵn sàng nhập học.","galleryDescription":"Ảnh từ các khóa học viên đã bay và trường đối tác tại Trung Quốc.","finalCtaDescription":"Nhận lộ trình chi tiết, danh sách trường và mức lương thực tế theo từng ngành — hoàn toàn miễn phí.","graduationImageUrls":[],"testimonialsHeading":"Học viên đi trước nói gì","heroSliderIntervalMs":4500,"graduationDescription":"🎓 Ngày 25/6/2026, Trường Đại học Công nghệ Điện tử Quế Lâm – Cơ sở Bắc Hải đã long trọng tổ chức Lễ tốt nghiệp và trao bằng cho sinh viên khóa 2026 với sự tham dự của Ban Giám hiệu nhà trường, lãnh đạo các đơn vị, khoa, phòng ban cùng đông đảo giảng viên và sinh viên.\\n\\nĐặc biệt, trong lễ tốt nghiệp năm nay có các sinh viên tốt nghiệp chương trình cao đẳng nghề thuộc Đề án “Một vành đai, Một con đường” mà chúng ta đã và đang triển khai. Các em được tham dự và nhận bằng trong cùng lễ tốt nghiệp chính thức của nhà trường với toàn thể sinh viên khóa 2026.\\n\\nĐây là một dấu mốc rất ý nghĩa, thể hiện sự ghi nhận của nhà trường đối với chương trình đào tạo, đồng thời khẳng định tính chính quy và sự gắn kết của chương trình trong hệ thống đào tạo của Trường Đại học Công nghệ Điện tử Quế Lâm."},"tracking":{"ga4Id":"","gtmId":"","events":{"lead":true,"click":true,"scroll":true,"pageView":true,"formStart":true,"completeRegistration":true},"customBody":"","customHead":"","customFooter":"","tiktokPixelId":"","facebookPixelId":"","tiktokAccessToken":"","googleVerification":""},"webhooks":[],"aiAdvisor":{"enabled":true,"keyRegions":"Nghệ An|Hà Tĩnh|Quảng Bình|Thanh Hóa|Quảng Ninh|Hải Phòng","weightDevice":20,"weightRegion":15,"weightScroll":15,"vipDeviceRegex":"iPhone (13|14|15|16) Pro|Pro Max|Galaxy S(22|23|24)|Fold|Flip","weightFastFill":15,"vipScrollPercent":70,"vipTimeOnPageSec":80,"weightTimeOnPage":20,"weightReturnVisit":15,"callScriptTemplate":"Chào {name}, em gọi từ chương trình du học nghề Trung Quốc. Em thấy anh/chị ở {city}, quan tâm ngành {major}. Dựa trên hành vi online, em đánh giá khách là {ai_rank} (score {ai_score}). Gợi ý: {sale_adv